INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('reading', '{"text": "Exercise is one of the simplest ways to improve both physical and mental health. Doctors recommend that adults get at least thirty minutes of moderate activity most days of the week. This can include walking, swimming, or cycling. Regular exercise helps control weight, strengthens the heart, and can even improve sleep quality. Many people find it easier to stay active when they exercise with a friend."}'::jsonb, '{"exact": "Exercise is one of the simplest ways to improve both physical and mental health. Doctors recommend that adults get at least thirty minutes of moderate activity most days of the week. This can include walking, swimming, or cycling. Regular exercise helps control weight, strengthens the heart, and can even improve sleep quality. Many people find it easier to stay active when they exercise with a friend."}'::jsonb, 68, 0.42, 'B1', 'approved', 'exam', 'health', 'b3000000-0000-4000-8000-000000000011', 1),
('reading', '{"text": "Smartphones have changed the way people communicate and access information. Today, most people carry a small computer in their pocket that can take photos, send messages, and browse the internet. While these devices offer many benefits, some experts worry that too much screen time can affect sleep and attention. Many schools and workplaces now encourage short breaks away from screens."}'::jsonb, '{"exact": "Smartphones have changed the way people communicate and access information. Today, most people carry a small computer in their pocket that can take photos, send messages, and browse the internet. While these devices offer many benefits, some experts worry that too much screen time can affect sleep and attention. Many schools and workplaces now encourage short breaks away from screens."}'::jsonb, 62, 0.45, 'B1', 'approved', 'exam', 'technology', 'b3000000-0000-4000-8000-000000000011', 2);
