INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('typing', '{"text": "Drinking enough water every day is essential for staying healthy. Water helps the body regulate temperature, transport nutrients, and remove waste. Most adults are advised to drink around eight glasses of water daily, although the exact amount can depend on activity level and climate. Many people forget to drink enough water simply because they do not feel thirsty until they are already somewhat dehydrated. Carrying a reusable water bottle throughout the day can serve as a helpful reminder. Even mild dehydration can cause tiredness, headaches, and difficulty concentrating, so maintaining good hydration habits is worth the small daily effort."}'::jsonb, '{"exact": "Drinking enough water every day is essential for staying healthy. Water helps the body regulate temperature, transport nutrients, and remove waste. Most adults are advised to drink around eight glasses of water daily, although the exact amount can depend on activity level and climate. Many people forget to drink enough water simply because they do not feel thirsty until they are already somewhat dehydrated. Carrying a reusable water bottle throughout the day can serve as a helpful reminder. Even mild dehydration can cause tiredness, headaches, and difficulty concentrating, so maintaining good hydration habits is worth the small daily effort."}'::jsonb, 97, 0.46, 'B1', 'approved', 'exam', 'health', 'b3000000-0000-4000-8000-000000000015', 1);
