INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('passage_reconstruction', '{"passage": "Leo decided to start running every morning before work. The first week felt very difficult, and he wanted to quit several times. By the third week, running became noticeably easier. After two months, Leo completed his first five-kilometer race feeling proud of his progress."}'::jsonb, '{"key_points": ["Leo started running every morning", "the first week was difficult", "it got easier by the third week", "he completed his first race after two months"]}'::jsonb, 45, 0.52, 'B1', 'approved', 'exam', 'health', 'b3000000-0000-4000-8000-000000000018', 1),
('passage_reconstruction', '{"passage": "Mia noticed her smartwatch was not tracking her sleep correctly anymore. She contacted the company''s support team for help right away. They suggested restarting the device and updating its software completely. After doing so, the watch began working perfectly again."}'::jsonb, '{"key_points": ["Mia''s smartwatch stopped tracking sleep correctly", "she contacted support", "they suggested restarting and updating it", "the watch worked perfectly afterward"]}'::jsonb, 40, 0.55, 'B2', 'approved', 'exam', 'technology', 'b3000000-0000-4000-8000-000000000018', 2),
('passage_reconstruction', '{"passage": "A local clinic started offering free health checkups once a month for residents. At first, only a few patients came to take advantage of the offer. Word spread quickly through the neighborhood, and soon all the appointments were fully booked for weeks ahead."}'::jsonb, '{"key_points": ["a clinic started offering free monthly checkups", "few patients came at first", "word spread through the neighborhood", "appointments became fully booked"]}'::jsonb, 43, 0.56, 'B2', 'approved', 'exam', 'health', 'b3000000-0000-4000-8000-000000000018', 3);
INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('summary_and_opinion', '{"passage": "In recent years, many parents and educators have debated whether schools should reduce the amount of homework given to students. Some schools have already started limiting homework, especially for younger children, while others continue to assign substantial amounts every night. This topic remains a source of disagreement among teachers, parents, and students themselves.\n\nThose who support reducing homework argue that children need time to rest, play, and spend time with family after a full day at school. They believe that too much homework can cause stress and reduce a child''s enthusiasm for learning. Supporters also point out that young children often learn just as effectively through play and real-world experiences as they do through repetitive written exercises at home.\n\nOn the other hand, many educators argue that homework plays an important role in reinforcing what students learn during class. They believe it teaches responsibility, time management, and independent thinking. Without homework, some teachers worry that students may struggle to retain information or develop strong study habits before reaching higher levels of education, where independent work becomes essential.\n\nBoth sides raise valid points about how children learn best. Reducing homework might improve a child''s wellbeing and enthusiasm for school, while keeping some homework may still support academic growth and discipline. Finding the right balance likely depends on a student''s age, needs, and the specific subject being taught, rather than a single answer that fits every situation."}'::jsonb, '{"key_points": ["schools debate reducing homework", "supporters say it reduces stress and frees family time", "educators say homework builds responsibility and retention", "the right balance depends on the student and subject"]}'::jsonb, 278, 0.60, 'B2', 'approved', 'exam', 'education', 'b3000000-0000-4000-8000-000000000019', 1);
